#!/usr/bin/env python3
"""Original solutions and exact task-specific scenes: Atanasyan 2023 V, 331–357.
Source printed95,103,104 (theory91–103) visually read. Author checks are not independent review.
"""
import json, math, re
from copy import deepcopy
from pathlib import Path
ROOT=Path(__file__).resolve().parents[2]
OUT=ROOT/'geometry-course/textbook'
EX,MODELS={},[]

def scene(points=(),segments=(),**kw):
 return dict(label=kw.pop('label','Условие'),points=list(points),segments=[list(s) for s in segments],**kw)
def tri(a='A',b='B',c='C'):return [[a,b],[b,c],[c,a]]
def arc(o,a,b,marks=0,radius=6):return dict(vertex=o,**{'from':a,'to':b},marks=marks,radius=radius)
def eq(a,b,marks=1):return dict(a=a,b=b,marks=marks)
def right(a,o,b):return dict(a=a,vertex=o,b=b,size=2.6)
def circle(o='O',r='_r'):return dict(center=o,through=r)
def ck(kind,**kw):return dict(type=kind,**kw)
def equal(*ss):return ck('equalLength',segments=[list(s) for s in ss])
def col(*ps):return ck('collinear',points=list(ps))
def par(a,b,c,d):return ck('parallel',segments=[[a,b],[c,d]])
def perp(a,b,c,d):return ck('perpendicular',segments=[[a,b],[c,d]])
def ang(a,o,b,d):return ck('angle',points=[a,o,b],degrees=d)
def ratio(a,b,c,d,x):return ck('distanceRatio',segments=[[a,b],[c,d]],ratio=x)
def S(prompt,text,reason,refs):return (prompt,text,reason,refs if isinstance(refs,list) else [refs])
def mid(a,b):return [(a[0]+b[0])/2,(a[1]+b[1])/2]
def dist(a,b):return math.hypot(a[0]-b[0],a[1]-b[1])
def interp(a,b,t):return [a[0]+t*(b[0]-a[0]),a[1]+t*(b[1]-a[1])]
def foot(p,a,b):
 u=[b[0]-a[0],b[1]-a[1]];t=((p[0]-a[0])*u[0]+(p[1]-a[1])*u[1])/(u[0]**2+u[1]**2)
 return interp(a,b,t)
def rotate(p,a):
 c,s=math.cos(math.radians(a)),math.sin(math.radians(a));return [p[0]*c-p[1]*s,p[0]*s+p[1]*c]
def unit(a,r=1):return [r*math.cos(math.radians(a)),r*math.sin(math.radians(a))]
def update(v,**kw):return dict(deepcopy(v),**kw)
def variant(p,v,suffix,label,unlock):
 names={k:('_'+k[1:]+suffix if k.startswith('_') else k+suffix) for k in p}
 def rename(z):
  if isinstance(z,str):return names.get(z,z)
  if isinstance(z,list):return [rename(q) for q in z]
  if isinstance(z,dict):return {k:rename(val) for k,val in z.items()}
  return z
 vv=rename(v);vv.update(label=label,availableFromStep=unlock)
 return {names[k]:v for k,v in p.items()},vv,{names[k]:k for k in p if not k.startswith('_')}
def add(n,part,condition,answer,steps,p,base,views=None,cases=(),checks=(),givens=(),labels=None,notes=(),offsets=None):
 pages=[95] if n<=335 else [103] if n<=346 else [103,104] if n==347 else [99,104] if n==354 else [104]
 vv={'neutral':deepcopy(base)};seq=views or [base]
 for i in range(len(steps)):
  vv[f'step-{i+1}']=deepcopy(seq[min(i,len(seq)-1)]);vv[f'step-{i+1}']['label']=f'Шаг {i+1}'
 for i,v in enumerate(cases,1):vv[f'case-{i}']=deepcopy(v)
 # Include the whole circumference in the uniform fit, including hidden later circles.
 extent=list(p.values());circ={(c['center'],c['through']) for v in vv.values() for c in v.get('circles',[])}
 for o,t in circ:
  x,y=p[o];r=dist(p[o],p[t]);extent.extend([(x-r,y-r),(x+r,y+r)])
 xs,ys=zip(*extent);s=min(76/(max(xs)-min(xs) or 1),48/(max(ys)-min(ys) or 1));cx=(min(xs)+max(xs))/2;cy=(min(ys)+max(ys))/2
 pp={k:[round(50+s*(x-cx),9),round(35+s*(y-cy),9),0] for k,(x,y) in p.items()}
 labs={k:k for k in p if not k.startswith('_')};labs.update(labels or {})
 labelonly=[k for k in labs if labs[k] in ['a','b','l','m','n','p','q']]
 off={k:[0,4.5] for k in labelonly}
 for o,t in circ:
  r=dist(p[o],p[t])
  for k in labs:
   if k==o or k in labelonly:continue
   if abs(dist(p[o],p[k])-r)<1e-7:
    d=[p[k][0]-p[o][0],p[k][1]-p[o][1]];off[k]=[round(4.5*d[0]/r,3),round(4.5*d[1]/r,3)]
 off.update(offsets or {})
 m=dict(points=pp,edges=[],planar=True,bounds=[0,0,100,70],views=vv,checks=list(checks),labels=labs,labelOnly=labelonly,labelOffsets=off,description='Чертёж относится к этой задаче. Дополнительные построения появляются на соответствующем шаге; отдельные случаи можно выбрать после их разбора.')
 item=dict(part=part,conditionSummary=condition,answer=answer,steps=[s[1] for s in steps],sourceVerified=True,mathVerified=True,visual=dict(initial='Только данные условия; искомые точки и вспомогательные линии скрыты.',stepChanges=['Построения и доказанные отметки появляются на своём шаге.'],cases=[v['label'] for v in cases]))
 EX.setdefault(n,dict(number=n,printedPages=pages,pdfPages=[x+1 for x in pages],parts=[],notes=[]))['parts'].append(item);EX[n]['notes'].extend(notes)
 MODELS.append(dict(chapter=5,collection='main',number=n,part=part,model=m,didactics=dict(steps=[dict(prompt=s[0],justification=s[2],theoryPoints=s[3]) for s in steps]),statementGivens=list(givens)))

#331: the whole plane requires two complete bisector lines, including their intersection.
p={'O':(0,0),'A':unit(28,3),'B':unit(-28,3),'_a':unit(208,3),'_b':unit(152,3),'_h':(3,0),'_v':(0,3),'M':(2,0)}
p['K']=foot(p['M'],p['O'],p['A']);p['L']=foot(p['M'],p['O'],p['B'])
b=scene('OAB',lines=[['_a','A'],['_b','B']]);bis=update(b,lines=b['lines']+[['O','_h'],['O','_v']]);proof=update(bis,points=list('OABMKL'),segments=[['M','K'],['M','L']],rightAngles=[right('M','K','O'),right('M','L','O')],equalSegments=[eq('M','K'),eq('M','L')])
add(331,'single','Определите геометрическое место всех точек плоскости, равноудалённых от двух пересекающихся прямых.','Две взаимно перпендикулярные прямые, содержащие биссектрисы четырёх образованных углов, включая точку пересечения данных прямых.',[
 S('Какие углы образуют данные прямые?','Обозначим их точку пересечения O. Получаются четыре угла; биссектрисы вертикальных углов образуют одну прямую. Имеются две такие биссекторные прямые.','Вертикальные углы и определение биссектрисы.',[11,39]),
 S('Подходят ли точки этих биссектрис?','Каждая точка M любой из четырёх биссектрис равноудалена от сторон своего угла, то есть от данных прямых. Точка O также подходит: оба расстояния равны нулю.','Прямое свойство биссектрисы.',39),
 S('Могут ли подходящие точки находиться вне них?','Пусть M равноудалена от прямых. Если M лежит на одной из них, нулевое расстояние до второй означает M = O. Иначе M находится внутри одного из четырёх углов и по обратному свойству принадлежит его биссектрисе.','Обратное свойство биссектрисы; расстояние до прямой.',[37,39]),
 S('Почему найдены именно две перпендикулярные прямые?','Смежные углы в сумме дают 180°, а их половины — 90°. Поэтому две биссекторные прямые перпендикулярны. Оба включения доказаны: других точек нет.','Смежные углы и определение геометрического места.',[11,39])],p,b,[bis,proof,bis,bis],checks=[perp('O','_h','O','_v'),perp('M','K','O','A'),perp('M','L','O','B'),equal(('M','K'),('M','L'))])

#332: exclude both exterior half-planes, not just prove one convenient direction.
p={'a':(3,1),'_a':(-3,1),'b':(3,-1),'_b':(-3,-1),'A':(-2,1),'B':(-2,-1),'M':(-2,0),'X':(1,0),'P':(1,1),'Q':(1,-1),'_mid':(3,0)}
b=scene('ab',lines=[['_a','a'],['_b','b']]);v1=update(b,points=list('abABM'),lines=b['lines']+[['M','_mid']],segments=[['A','B']],equalSegments=[eq('A','M'),eq('M','B')],rightAngles=[right('A','B','b')]);v2=update(b,points=list('abMXPQ'),lines=b['lines']+[['M','_mid']],segments=[['P','Q']],rightAngles=[right('X','P','a'),right('X','Q','b')],equalSegments=[eq('P','X'),eq('X','Q')]);end=update(b,points=list('abM'),lines=b['lines']+[['M','_mid']])
add(332,'single','Определите геометрическое место всех точек плоскости, равноудалённых от двух данных параллельных прямых.','Прямая, параллельная данным и проходящая посередине между ними.',[
 S('Как построить среднюю прямую?','Проведём общий перпендикуляр AB к данным прямым, отметим середину M отрезка AB и проведём через M прямую l, параллельную данным.','Построение перпендикуляра, середины и параллельной.',[16,23,28]),
 S('Почему каждая точка l подходит?','Пусть X принадлежит l, а P и Q — основания перпендикуляров на данные прямые. Расстояния между параллельными постоянны: XP = MA и XQ = MB. Так как MA = MB, получаем XP = XQ.','Расстояние между параллельными прямыми.',37),
 S('Почему снаружи полосы нет решений?','Вне полосы перпендикуляр до дальней прямой состоит из расстояния до ближней и положительного расстояния между прямыми. Эти расстояния не равны. На границе полосы одно расстояние нулевое, другое положительное.','Сложение отрезков на общем перпендикуляре.',[7,37]),
 S('Где находится любая подходящая точка внутри полосы?','Если XP = XQ, то X — середина перпендикулярного отрезка PQ. Значит её расстояние до каждой границы равно половине расстояния между прямыми. По геометрическому месту из пункта 37 она лежит на построенной l.','Геометрическое место точек на заданном расстоянии от прямой.',37)],p,b,[v1,v2,end,end],checks=[par('_a','a','_b','b'),par('M','_mid','_a','a'),equal(('A','M'),('M','B'),('P','X'),('X','Q')),perp('A','B','_a','a')])

#333: intersecting, distinct parallel, and coincident perpendicular bisectors.
p={'A':(-3,-1),'B':(-3,1),'C':(0,-2),'D':(2,0),'E':(-3,0),'F':(1,-1),'M':(0,0)}
b=scene('ABCD',[['A','B'],['C','D']]);v1=update(b,points=list('ABCDE'),lines=[['E','M']],equalSegments=[eq('A','E'),eq('E','B')],rightAngles=[right('A','E','M')]);v2=update(v1,points=list('ABCDEF'),lines=[['E','M'],['F','M']],equalSegments=[eq('A','E'),eq('E','B'),eq('C','F',2),eq('F','D',2)],rightAngles=[right('A','E','M'),right('C','F','M')]);v3=update(v2,points=list('ABCDEFM'))
cases=[];labels={}
for suffix,label,unlock,q in [('p','Серединные перпендикуляры параллельны',4,{'A':(-2,-1),'B':(-2,1),'C':(2,1.5),'D':(2,3.5),'E':(-2,0),'F':(2,2.5),'_e':(2,0),'_f':(-2,2.5)}),('c','Серединные перпендикуляры совпадают',5,{'A':(-2,-1),'B':(-2,1),'C':(2,-2),'D':(2,2),'E':(-2,0),'F':(2,0),'M':(0,0)})]:
 v=scene([k for k in q if not k.startswith('_')],[['A','B'],['C','D']],lines=[['E','_e'],['F','_f']] if suffix=='p' else [['E','F']],equalSegments=[eq('A','E'),eq('E','B'),eq('C','F',2),eq('F','D',2)])
 qp,qv,ql=variant(q,v,suffix,label,unlock);p.update(qp);cases.append(qv);labels.update(ql)
add(333,'single','Даны отрезки AB и CD. Постройте точку M, для которой MA = MB и MC = MD.','Искомые точки — пересечение серединных перпендикуляров к AB и CD: одна точка, ни одной или бесконечно много.',[
 S('Где выполняется первое равенство?','Построим середину E отрезка AB и перпендикуляр p к AB через E. Равенство MA = MB выполняется в точности для точек p.','Геометрическое место точек, равноудалённых от концов отрезка.',40),
 S('Где выполняется второе равенство?','Аналогично построим серединный перпендикуляр q к CD через его середину F. На q и только на q выполняется MC = MD.','То же геометрическое место для CD.',40),
 S('Что делать, если p и q пересекаются?','Их точка пересечения M удовлетворяет обоим равенствам. Она единственна: любая искомая точка обязана лежать на обеих прямых.','Пересечение двух геометрических мест.',40),
 S('А если прямые различны и параллельны?','Общих точек у p и q нет, поэтому построение невозможно: решений нет.','Определение параллельных прямых.',24),
 S('Что происходит при совпадении прямых?','Если p и q совпали, любая точка этой прямой подходит. Решений бесконечно много; можно выбрать любую такую M.','Оба условия выполняются на одной и той же прямой.',40)],p,b,[v1,v2,v3,cases[0],cases[1]],cases=cases,checks=[equal(('M','A'),('M','B')),equal(('M','C'),('M','D')),perp('A','B','E','M'),perp('C','D','F','M')],labels=labels)

#334: the source does not require M to be inside the angle; sides mean supporting lines (p92 footnote).
p={'O':(-3,0),'U':(-1,2),'V':(-1,-2),'A':(0,-1),'B':(2,3),'E':(1,1),'M':(3,0),'N':(-3,3),'_h':(1,0),'_v':(-3,4)}
b=scene('OUVAB',[['A','B']],rays=[['O','U'],['O','V']]);v1=update(b,points=list('OUVABE'),lines=[['E','M']],equalSegments=[eq('A','E'),eq('E','B')],rightAngles=[right('A','E','M')]);v2=update(v1,lines=[['E','M'],['O','_h'],['O','_v']]);v3=update(v2,points=list('OUVABEMN'))
cases=[];labels={}
for suf,label,unlock,q in [('p','Одна точка: параллельно одной биссектрисе',4,{'O':(-3,0),'U':(-1,2),'V':(-1,-2),'A':(1,1),'B':(1,3),'E':(1,2),'N':(-3,2),'_h':(1,0),'_v':(-3,3)}),('o','Одна точка: вершина угла',4,{'O':(-3,0),'U':(-1,2),'V':(-1,-2),'A':(-1,1),'B':(-5,-1),'_e':(-4,2),'_h':(1,0),'_v':(-3,3)}),('c','Бесконечно много точек',5,{'O':(-3,0),'U':(-1,2),'V':(-1,-2),'A':(1,-1),'B':(1,1),'E':(1,0),'M':(-.5,0),'_h':(3,0),'_v':(-3,3)})]:
 ls=[['O','_h'],['O','_v']]+([['E','N']] if suf=='p' else [['O','_e']] if suf=='o' else [])
 v=scene([k for k in q if not k.startswith('_')],[['A','B']],rays=[['O','U'],['O','V']],lines=ls)
 qp,qv,ql=variant(q,v,suf,label,unlock);p.update(qp);cases.append(qv);labels.update(ql)
add(334,'single','Даны угол и отрезок AB. Постройте точку M, равноудалённую от сторон угла и такую, что MA = MB.','Пересечения серединного перпендикуляра к AB с двумя биссекторными прямыми сторон угла; решений одна или две точки либо бесконечно много.',[
 S('Как обеспечить MA = MB?','Построим серединный перпендикуляр p к AB. Все искомые точки должны лежать на p.','Свойство серединного перпендикуляра.',40),
 S('Где выполняется условие о расстояниях?','Расстояние до стороны понимается как расстояние до содержащей её прямой. По задаче 331 точки, равноудалённые от двух пересекающихся прямых, составляют две биссекторные прямые. Построим их.','Свойства биссектрисы, включая смежный угол.',[39,11]),
 S('Как получить и проверить решения?','Найдём пересечения p с этими двумя прямыми. Каждая найденная точка равноудалена от A и B и от прямых сторон угла. Обратно, любая подходящая точка принадлежит этим пересечениям. На основном чертеже это M и N.','Пересечение геометрических мест; два направления проверки.',[39,40]),
 S('Когда имеется только одна точка?','Если p параллельна одной биссекторной прямой, она пересекает вторую в одной точке. Если p проходит через вершину угла и не совпадает с биссекторной прямой, обе найденные точки совпадают с вершиной. Нулевые расстояния здесь допустимы.','Биссекторные прямые перпендикулярны; точка не обязана лежать внутри угла.',[11,39,40]),
 S('Когда решений бесконечно много?','При совпадении p с одной из биссекторных прямых любая её точка подходит. Иначе остаются одна или две точки. Отсутствия решений при таком понимании расстояний нет: прямая не может быть параллельна двум перпендикулярным прямым.','Взаимное расположение прямых.',[24,29]),
 S('Как изменится задача при дополнительном требовании «внутри угла»?','Тогда нужно оставить только точки внутреннего луча-биссектрисы; вершина не является внутренней точкой. После такого ограничения решений может не оказаться. В исходном условии это ограничение не задано.','Различение исходного условия и дополнительного ограничения.',39)],p,b,[v1,v2,v3,cases[0],cases[2],v3],cases=cases,checks=[equal(('M','A'),('M','B')),equal(('N','A'),('N','B')),perp('A','B','E','M')],labels=labels,notes=['Источник p95 не требует, чтобы M лежала внутри угла; p92 уточняет расстояние до содержащих стороны прямых. Рассмотрено полное множество решений.'])

