for k,a,c in [('K','A','B'),('L','B','C'),('N','C','A')]:p[k]=foot(p['O'],p[a],p[c])
b=scene('ABCO',tri()+[['B','O'],['C','O']],dashSegments=[['B','_b'],['C','_c']]);v1=update(b,points=list('ABCOKL'),segments=tri()+[['B','O'],['O','K'],['O','L']],rightAngles=[right('O','K','B'),right('O','L','B')]);v2=update(b,points=list('ABCOLN'),segments=tri()+[['C','O'],['O','L'],['O','N']],rightAngles=[right('O','L','C'),right('O','N','C')]);end=scene('ABCO',tri(),dashSegments=[['B','_b'],['C','_c']],note='Все три расстояния равны. Основания перпендикуляров доступны на предыдущих шагах.')
add(335,'single','Биссектрисы внешних углов B и C треугольника ABC пересекаются в O. Докажите, что O равноудалена от прямых AB, BC и CA.','Расстояния от O до AB, BC и CA равны.',[
 S('Что даёт внешняя биссектриса при B?','Опустим из O перпендикуляры OK и OL на прямые AB и BC. Точка O лежит на биссекторной прямой внешнего угла B, поэтому OK = OL.','Равноудалённость точек биссектрисы от прямых сторон.',39),
 S('Что даёт внешняя биссектриса при C?','Опустим ON на прямую CA. По свойству внешней биссектрисы при C получаем OL = ON.','То же свойство биссектрисы.',39),
 S('Как связать три расстояния?','Из OK = OL и OL = ON следует OK = OL = ON. Это и есть равенство расстояний от O до трёх прямых. Основания K и N могут лежать на продолжениях сторон: речь именно о прямых.','Определение расстояния от точки до прямой и транзитивность равенства.',[37,39])],p,b,[v1,v2,end],checks=[perp('O','K','A','B'),perp('O','L','B','C'),perp('O','N','C','A'),equal(('O','K'),('O','L'),('O','N'))])

#336–339: no cosine rule or inscribed-angle theorem from later chapters.
